using namespace std;

struct AnalysisResult {
    string file;
    double avg_response_time;
    map<double, int> satisfaction_dist;
    map<string, int> common_issues;
    map<string, double> daily_sales;
    map<string, int> product_rank;
};

void process_file(const string& file_path, mutex& mtx, vector<AnalysisResult>& results) {
    try {
        ifstream file(file_path);
        if (!file) throw runtime_error("File not found");

        string line;
        vector<string> rows;
        while (getline(file, line)) rows.push_back(line);

        // Data cleaning
        map<string, bool> seen;
        for (auto& row : rows) {
            if (row.empty()) continue;
            if (seen[row]) continue;
            seen[row] = true;
        }

        // Simple text processing
        for (auto& row : rows) {
            if (row.find(',') != string::npos) {
                stringstream ss(row);
                string col;
                vector<string> cols;
                while (getline(ss, col, ',')) cols.push_back(col);
                if (cols.size() > 1) {
                    cols[2] = regex_replace(cols[2], regex(R"([^\w\s])"), "");
                    cols[2] = tolower(cols[2]);
                }
                rows[distance(rows.begin(), &row)] = join(cols, ",");
            }
        }

        // Analysis (simplified)
        AnalysisResult res;
        res.file = file_path;

        // Simulate NLP analysis
        res.avg_response_time = 120.0;
        res.satisfaction_dist = {{0.5, 100}, {-0.3, 50}};
        res.common_issues = {{"payment", 30}, {"return", 20}};

        lock_guard<mutex> lock(mtx);
        results.push_back(res);
    } catch (const exception& e) {
        cerr << "Error processing " << file_path << ": " << e.what() << endl;
    }
}

int main() {
    mutex mtx;
    vector<AnalysisResult> results;
    vector<thread> threads;

    // Simulated data directory
    vector<string> files = {"data1.csv", "data2.json"};

    auto start = chrono::steady_clock::now();
    cout << "Processing started at " << chrono::duration_cast<chrono::seconds>(start.time_since_epoch()).count() << endl;

    for (const auto& file : files) {
        threads.emplace_back(process_file, file, ref(mtx), ref(results));
    }

    for (auto& t : threads) t.join();

    // Simulate database write
    sqlite3* db;
    if (sqlite3_open("analysis.db", &db) == SQLITE_OK) {
        for (const auto& res : results) {
            stringstream ss;
            ss << "INSERT INTO chat_analysis (file, avg_response_time, satisfaction_dist, common_issues) VALUES ('" 
               << res.file << "', " << res.avg_response_time << ", '" 
               << to_string(res.satisfaction_dist) << "', '" 
               << to_string(res.common_issues) << "')";
            sqlite3_exec(db, ss.str().c_str(), nullptr, nullptr, nullptr);
        }
        sqlite3_close(db);
    }

    auto end = chrono::steady_clock::now();
    cout << "Processing completed in " << chrono::duration_cast<chrono::seconds>(end.time_since_epoch()).count() - chrono::duration_cast<chrono::seconds>(start.time_since_epoch()).count() << " seconds" << endl;

    return 0;
}
