#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <regex>
#include <sqlite3.h>
#include <chrono>
#include <string>
#include <sstream>

using namespace std;

// 定义分析结果结构体，包含文件路径、平均响应时间、满意度分布、常见问题等字段
struct AnalysisResult {
    string file;                // 文件路径
    double avg_response_time;   // 平均响应时间
    map<double, int> satisfaction_dist;  // 满意度分布（极性值 -> 出现次数）
    map<string, int> common_issues;      // 常见问题类型（关键词 -> 出现次数）
    map<string, double> daily_sales;     // 每日销售额（日期 -> 销售额）
    map<string, int> product_rank;       // 产品销量排名（产品ID -> 销量）
};

// 处理单个文件的函数，包含数据清洗、分析和结果存储
void process_file(const string& file_path, mutex& mtx, vector<AnalysisResult>& results) {
    try {
        // 打开文件并读取所有行
        ifstream file(file_path);
        if (!file) throw runtime_error("文件未找到");  // 文件读取失败异常

        string line;
        vector<string> rows;  // 存储所有行数据
        while (getline(file, line)) rows.push_back(line);  // 读取所有行

        // 数据清洗：去重（使用map自动去重）
        map<string, bool> seen;
        for (auto& row : rows) {
            if (row.empty()) continue;  // 跳过空行
            if (seen[row]) continue;    // 如果已存在，跳过
            seen[row] = true;           // 标记为已处理
        }

        // 文本标准化处理（模拟CSV格式处理）
        for (auto& row : rows) {
            if (row.find(',') != string::npos) {  // 检查是否为CSV格式
                stringstream ss(row);
                string col;
                vector<string> cols;  // 分割后的列数据
                while (getline(ss, col, ',')) cols.push_back(col);  // 按逗号分割
                if (cols.size() > 1) {  // 确保有至少两列
                    // 对第三列进行文本标准化：去除特殊符号、转换为小写
                    cols[2] = regex_replace(cols[2], regex(R"([^\w\s])"), "");
                    cols[2] = tolower(cols[2]);  // 转换为小写
                }
                // 重新拼接行数据
                rows[distance(rows.begin(), &row)] = join(cols, ",");  // 使用join函数拼接
            }
        }

        // 模拟NLP分析（实际应用中需替换为完整NLP处理）
        AnalysisResult res;  // 初始化分析结果
        res.file = file_path;  // 设置文件路径

        // 模拟平均响应时间（实际应从数据中计算）
        res.avg_response_time = 120.0;  // 示例值

        // 模拟满意度分布（实际应通过情感分析计算）
        res.satisfaction_dist = {{0.5, 100}, {-0.3, 50}};  // 示例值

        // 模拟常见问题类型（实际应通过关键词提取）
        res.common_issues = {{"payment", 30}, {"return", 20}};  // 示例值

        // 使用锁保护共享资源（results向量）
        lock_guard<mutex> lock(mtx);
        results.push_back(res);  // 将结果添加到全局结果列表
    } catch (const exception& e) {
        // 异常处理：记录文件处理错误
        cerr << "处理文件 " << file_path << " 时出错: " << e.what() << endl;
    }
}

// 主函数：程序入口点
int main() {
    mutex mtx;  // 互斥锁，用于线程安全访问共享资源
    vector<AnalysisResult> results;  // 存储所有分析结果
    vector<thread> threads;  // 线程列表

    // 模拟数据目录（实际应遍历真实目录）
    vector<string> files = {"data1.csv", "data2.json"};

    // 记录处理开始时间
    auto start = chrono::steady_clock::now();
    cout << "处理开始于 " << chrono::duration_cast<chrono::seconds>(start.time_since_epoch()).count() << endl;

    // 创建并启动线程处理每个文件
    for (const auto& file : files) {
        threads.emplace_back(process_file, file, ref(mtx), ref(results));  // 调用process_file函数
    }

    // 等待所有线程完成
    for (auto& t : threads) t.join();

    // 模拟数据库写入（使用SQLite C API）
    sqlite3* db;
    if (sqlite3_open("analysis.db", &db) == SQLITE_OK) {  // 打开数据库
        for (const auto& res : results) {
            // 构建SQL插入语句（注意转义和格式化）
            stringstream ss;
            ss << "INSERT INTO chat_analysis (file, avg_response_time, satisfaction_dist, common_issues) VALUES ('" 
               << res.file << "', " << res.avg_response_time << ", '" 
               << to_string(res.satisfaction_dist) << "', '" 
               << to_string(res.common_issues) << "')";
            sqlite3_exec(db, ss.str().c_str(), nullptr, nullptr, nullptr);  // 执行SQL
        }
        sqlite3_close(db);  // 关闭数据库连接
    }

    // 记录处理结束时间并计算耗时
    auto end = chrono::steady_clock::now();
    cout << "处理完成，耗时 " << chrono::duration_cast<chrono::seconds>(end.time_since_epoch()).count() 
         << " 秒" << endl;

    return 0;
}
