```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <sstream>
#include <cmath>
#include <nlohmann/json.hpp>
#include <sqlite3.h>
#include <boost/algorithm/string.hpp>

using json = nlohmann::json;

// Configuration
constexpr char DATA_DIR[] = "/data/customer_logs";
constexpr char DB_FILE[] = "analysis.db";
constexpr int THREAD_COUNT = 4;

// Sentiment analysis (simplified)
double sentimentScore(const std::string& text) {
    int pos = 0, neg = 0;
    std::istringstream iss(text);
    std::string word;
    while (iss >> word) {
        if (boost::starts_with(word, "good") || boost::starts_with(word, "happy"))
            pos++;
        else if (boost::starts_with(word, "bad") || boost::starts_with(word, "sad"))
            neg++;
    }
    return static_cast<double>(pos - neg) / (pos + neg);
}

// Data cleaning and processing
void processSupportFile(const std::string& file) {
    std::ifstream ifs(file);
    json data;
    ifs >> data;

    std::map<std::string, int> keywords;
    double totalSentiment = 0.0;
    double totalResponse = 0.0;

    for (const auto& msg : data) {
        std::string text = msg["text"];
        boost::to_lower(text);
        boost::erase_all(text, " ");
        std::istringstream iss(text);
        std::string word;
        while (iss >> word) {
            keywords[word]++;
        }
        totalSentiment += sentimentScore(msg["text"]);
        totalResponse += msg["response_time"];
    }

    std::lock_guard<std::mutex> lock(g_mutex);
    std::cout << "Processed: " << file << std::endl;
    // Save to DB
    sqlite3* db;
    sqlite3_open(DB_FILE, &db);
    std::string query = "INSERT INTO support (keywords, sentiment, response_time) VALUES ('" + 
                        json::to_string(keywords) + "', " + std::to_string(totalSentiment) + ", " + 
                        std::to_string(totalResponse) + ")";
    sqlite3_exec(db, query.c_str(), nullptr, nullptr, nullptr);
    sqlite3_close(db);
}

void processTransactionFile(const std::string& file) {
    std::ifstream ifs(file);
    std::vector<std::map<std::string, std::string>> data;
    std::string line;
    while (std::getline(ifs, line)) {
        std::istringstream iss(line);
        std::map<std::string, std::string> row;
        std::string key, value;
        while (iss >> key >> value) {
            row[key] = value;
        }
        data.push_back(row);
    }

    std::map<std::string, double> dailySales;
    std::map<std::string, int> productRanking;

    for (const auto& row : data) {
        std::string date = row["date"];
        double amount = std::stod(row["amount"]);
        dailySales[date] += amount;
        productRanking[row["product"]]++;
    }

    std::lock_guard<std::mutex> lock(g_mutex);
    std::cout << "Processed: " << file << std::endl;
    // Save to DB
    sqlite3* db;
    sqlite3_open(DB_FILE, &db);
    std::string query = "INSERT INTO transactions (date, amount, product) VALUES ";
    for (const auto& row : data) {
        query += "('" + row["date"] + "', " + row["amount"] + ", '" + row["product"] + "'), ";
    }
    query.pop_back();
    sqlite3_exec(db, query.c_str(), nullptr, nullptr, nullptr);
    sqlite3_close(db);
}

int main() {
    std::mutex g_mutex;
    std::vector<std::thread> threads;

    std::cout << "Starting processing..." << std::endl;
    std::vector<std::string> files;
    for (const auto& entry : std::filesystem::directory_iterator(DATA_DIR)) {
        files.push_back(entry.path().string());
    }

    for (int i = 0; i < THREAD_COUNT && i < files.size(); ++i) {
        threads.emplace_back(processSupportFile, files[i]);
    }

    for (int i = THREAD_COUNT; i < files.size(); ++i) {
        threads.emplace_back(processTransactionFile, files[i]);
    }

    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Processing completed." << std::endl;
    return 0;
}
```

