このコードは、C++でPythonの機能を再現する基本的な実装です。追加の機能やパフォーマンス最適化が必要な場合は、ご質問ください。

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <sstream>
#include <cmath>
#include <nlohmann/json.hpp>
#include <sqlite3.h>
#include <boost/algorithm/string.hpp>

using json = nlohmann::json;

// Configuration
constexpr char DATA_DIR[] = "/data/customer_logs";  // データディレクトリの設定
constexpr char DB_FILE[] = "analysis.db";           // データベースファイル名
constexpr int THREAD_COUNT = 4;                     // マルチスレッド数

// 簡易的な感情分析関数
// トークン単位で正・負のキーワードをカウントし、スコアを計算
double sentimentScore(const std::string& text) {
    int pos = 0, neg = 0;
    std::istringstream iss(text);
    std::string word;
    while (iss >> word) {
        // 正の感情キーワード（例: good, happy）の検出
        if (boost::starts_with(word, "good") || boost::starts_with(word, "happy"))
            pos++;
        // 負の感情キーワード（例: bad, sad）の検出
        else if (boost::starts_with(word, "bad") || boost::starts_with(word, "sad"))
            neg++;
    }
    // スコア計算: (正のキーワード数 - 負のキーワード数) / 総キーワード数
    return static_cast<double>(pos - neg) / (pos + neg);
}

// カスタマーサポートチャットファイルの処理
void processSupportFile(const std::string& file) {
    std::ifstream ifs(file);  // ファイルを開く
    json data;                // JSONデータを格納する変数
    ifs >> data;              // JSONデータを読み込む

    std::map<std::string, int> keywords;        // キーワードカウント
    double totalSentiment = 0.0;                // 総感情スコア
    double totalResponse = 0.0;                 // 総応答時間

    // JSONデータをループして処理
    for (const auto& msg : data) {
        std::string text = msg["text"];         // テキスト取得
        boost::to_lower(text);                  // 小文字化
        boost::erase_all(text, " ");            // 空白削除
        std::istringstream iss(text);           // テキストをトークンに分割
        std::string word;
        while (iss >> word) {
            keywords[word]++;                   // キーワードカウント
        }
        totalSentiment += sentimentScore(msg["text"]);  // 感情スコア累積
        totalResponse += msg["response_time"];  // 応答時間累積
    }

    std::lock_guard<std::mutex> lock(g_mutex);  // データベース操作の排他制御
    std::cout << "Processed: " << file << std::endl;  // プログレス表示

    // SQLiteデータベースに結果を保存
    sqlite3* db;
    sqlite3_open(DB_FILE, &db);  // データベース接続
    std::string query = "INSERT INTO support (keywords, sentiment, response_time) VALUES ('" + 
                        json::to_string(keywords) + "', " + std::to_string(totalSentiment) + ", " + 
                        std::to_string(totalResponse) + ")";
    sqlite3_exec(db, query.c_str(), nullptr, nullptr, nullptr);  // SQL実行
    sqlite3_close(db);  // データベースクローズ
}

// 取引履歴CSVファイルの処理
void processTransactionFile(const std::string& file) {
    std::ifstream ifs(file);  // ファイルを開く
    std::vector<std::map<std::string, std::string>> data;  // データを格納するベクター
    std::string line;
    while (std::getline(ifs, line)) {  // 行単位で読み込み
        std::istringstream iss(line);
        std::map<std::string, std::string> row;
        std::string key, value;
        while (iss >> key >> value) {
            row[key] = value;  // キー値ペアをマップに格納
        }
        data.push_back(row);
    }

    std::map<std::string, double> dailySales;         // 日次売上
    std::map<std::string, int> productRanking;        // 人気製品

    // データをループして集計
    for (const auto& row : data) {
        std::string date = row["date"];          // 日付取得
        double amount = std::stod(row["amount"]);  // 売上金額変換
        dailySales[date] += amount;             // 日次売上集計
        productRanking[row["product"]]++;        // 人気製品集計
    }

    std::lock_guard<std::mutex> lock(g_mutex);  // データベース操作の排他制御
    std::cout << "Processed: " << file << std::endl;  // プログレス表示

    // SQLiteデータベースに結果を保存
    sqlite3* db;
    sqlite3_open(DB_FILE, &db);  // データベース接続
    std::string query = "INSERT INTO transactions (date, amount, product) VALUES ";
    for (const auto& row : data) {
        query += "('" + row["date"] + "', " + row["amount"] + ", '" + row["product"] + "'), ";
    }
    query.pop_back();  // 最後のカンマを削除
    sqlite3_exec(db, query.c_str(), nullptr, nullptr, nullptr);  // SQL実行
    sqlite3_close(db);  // データベースクローズ
}

int main() {
    std::mutex g_mutex;  // マルチスレッド時の排他制御用ミューテックス
    std::vector<std::thread> threads;  // スレッドを管理するベクター

    std::cout << "Starting processing..." << std::endl;  // プログラム開始メッセージ

    // データディレクトリ内のファイルを列挙
    std::vector<std::string> files;
    for (const auto& entry : std::filesystem::directory_iterator(DATA_DIR)) {
        files.push_back(entry.path().string());
    }

    // マルチスレッドで処理を実行
    for (int i = 0; i < THREAD_COUNT && i < files.size(); ++i) {
        threads.emplace_back(processSupportFile, files[i]);  // サポートファイル処理スレッド
    }

    for (int i = THREAD_COUNT; i < files.size(); ++i) {
        threads.emplace_back(processTransactionFile, files[i]);  // 取引ファイル処理スレッド
    }

    // すべてのスレッドを完了まで待機
    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Processing completed." << std::endl;  // プログラム終了メッセージ
    return 0;
}
```

**コードの構造とコメントの説明**  
1. **データ処理関数**  
   - `sentimentScore`: 簡易的な感情分析を実装（単語ベースのスコア計算）  
   - `processSupportFile`: JSONファイルの処理（テキストクリーニング、キーワード抽出、感情分析）  
   - `processTransactionFile`: CSVファイルの処理（日次売上集計、人気製品分析）  

2. **並列処理**  
   - `std::thread`でマルチスレッド処理を実装  
   - データベース操作に`std::lock_guard<std::mutex>`で排他制御  

3. **データベース連携**  
   - SQLiteデータベースに結果を保存（`sqlite3`ライブラリ使用）  

4. **リアルタイム進捗表示**  
   - コンソールに処理ファイルを表示（`std::cout`）  

